import { mkdir, readFile, writeFile, unlink } from 'node:fs/promises';
import { dirname, posix, resolve, sep } from 'node:path';
import { getServerConfig } from '@/lib/config';

/**
 * File storage.
 *
 * Phase 1 ships a local-disk driver that is safe for development and single
 * server deployments. The interface is intentionally small so that object
 * storage (Supabase Storage / S3) can be added later without touching feature
 * code. See ARCHITECTURE.md.
 *
 * Security: storage keys are generated by the server (never from user input),
 * and every resolved path is verified to stay inside the storage root.
 */
export type StoredObject = {
  key: string;
  contentType: string;
  size: number;
};

export interface StorageDriver {
  save(key: string, data: Buffer, contentType: string): Promise<StoredObject>;
  read(key: string): Promise<{ data: Buffer; contentType: string } | null>;
  remove(key: string): Promise<void>;
}

function storageRoot(): string {
  return resolve(process.cwd(), getServerConfig().STORAGE_LOCAL_DIR);
}

function resolveKey(key: string): string {
  const root = storageRoot();
  const target = resolve(root, key);
  if (target !== root && !target.startsWith(root + sep)) {
    throw new Error('Refusing to access a path outside the storage directory');
  }
  return target;
}

const localDriver: StorageDriver = {
  async save(key, data, contentType) {
    const target = resolveKey(key);
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, data);
    return { key, contentType, size: data.byteLength };
  },

  async read(key) {
    try {
      const target = resolveKey(key);
      const data = await readFile(target);
      return { data, contentType: contentTypeFromKey(key) };
    } catch {
      return null;
    }
  },

  async remove(key) {
    try {
      await unlink(resolveKey(key));
    } catch {
      // Missing file is not an error for a delete.
    }
  },
};

export function getStorage(): StorageDriver {
  const { STORAGE_DRIVER } = getServerConfig();
  switch (STORAGE_DRIVER) {
    case 'local':
    default:
      return localDriver;
  }
}

function contentTypeFromKey(key: string): string {
  const extension = key.split('.').pop()?.toLowerCase();
  switch (extension) {
    case 'png':
      return 'image/png';
    case 'jpg':
    case 'jpeg':
      return 'image/jpeg';
    case 'webp':
      return 'image/webp';
    default:
      return 'application/octet-stream';
  }
}

// ---------------------------------------------------------------------------
// Upload validation
// ---------------------------------------------------------------------------

const IMAGE_SIGNATURES: Array<{ extension: string; contentType: string; matches: (b: Buffer) => boolean }> = [
  {
    extension: 'png',
    contentType: 'image/png',
    matches: (buffer) =>
      buffer.length > 8 &&
      buffer[0] === 0x89 &&
      buffer[1] === 0x50 &&
      buffer[2] === 0x4e &&
      buffer[3] === 0x47 &&
      buffer[4] === 0x0d &&
      buffer[5] === 0x0a &&
      buffer[6] === 0x1a &&
      buffer[7] === 0x0a,
  },
  {
    extension: 'jpg',
    contentType: 'image/jpeg',
    matches: (buffer) =>
      buffer.length > 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff,
  },
  {
    extension: 'webp',
    contentType: 'image/webp',
    matches: (buffer) =>
      buffer.length > 12 &&
      buffer.subarray(0, 4).toString('ascii') === 'RIFF' &&
      buffer.subarray(8, 12).toString('ascii') === 'WEBP',
  },
];

export type ImageValidationResult =
  | { ok: true; data: Buffer; contentType: string; extension: string }
  | { ok: false; error: string };

/**
 * Validate an uploaded logo by content, not by the filename or the client's
 * declared MIME type (both are attacker controlled). SVG is deliberately
 * rejected: it can carry scripts and would be an XSS vector when served.
 */
export async function validateLogoUpload(file: File): Promise<ImageValidationResult> {
  const { MAX_UPLOAD_BYTES } = getServerConfig();

  if (!file || file.size === 0) {
    return { ok: false, error: 'Choose an image file to upload.' };
  }
  if (file.size > MAX_UPLOAD_BYTES) {
    const limitMb = (MAX_UPLOAD_BYTES / (1024 * 1024)).toFixed(1);
    return { ok: false, error: `The file is too large. Maximum size is ${limitMb} MB.` };
  }

  const data = Buffer.from(await file.arrayBuffer());
  const signature = IMAGE_SIGNATURES.find((candidate) => candidate.matches(data));

  if (!signature) {
    return { ok: false, error: 'Upload a PNG, JPEG or WebP image.' };
  }

  return { ok: true, data, contentType: signature.contentType, extension: signature.extension };
}

/** Storage key for a business logo: server-generated, one file per upload. */
export function logoStorageKey(businessId: string, extension: string): string {
  return posix.join(
    'logos',
    businessId,
    `${Date.now()}-${Math.random().toString(36).slice(2, 10)}.${extension}`
  );
}
